import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        FastScanner fs = new FastScanner();
        int n = fs.nextInt();
        int t = fs.nextInt();

        // dp[i][h][p][prev] = number of sequences of length i,
        // having h humps so far,
        // previous trend p (0: up, 1: down),
        // and last value prev (1..4)
        long[][][][] dp = new long[n + 1][t + 2][2][5];

        // Initialize sequences of length 2
        for (int y1 = 1; y1 <= 4; y1++) {
            for (int y2 = 1; y2 <= 4; y2++) {
                if (y1 == y2) continue;
                int trend = (y2 > y1) ? 0 : 1;
                dp[2][0][trend][y2] += 1;
            }
        }

        // Transition for lengths 3 to n
        for (int len = 3; len <= n; len++) {
            for (int h = 0; h <= t; h++) {
                for (int p = 0; p < 2; p++) {
                    for (int prev = 1; prev <= 4; prev++) {
                        long curVal = dp[len - 1][h][p][prev];
                        if (curVal == 0) continue;
                        for (int cur = 1; cur <= 4; cur++) {
                            if (cur == prev) continue;
                            int newTrend = (cur > prev) ? 0 : 1;
                            int newH = h;
                            if (p == 0 && newTrend == 1) { // up -> down: hump
                                newH++;
                            }
                            if (newH <= t) {
                                dp[len][newH][newTrend][cur] += curVal;
                            }
                        }
                    }
                }
            }
        }

        long ans = 0;
        for (int p = 0; p < 2; p++) {
            for (int last = 1; last <= 4; last++) {
                ans += dp[n][t][p][last];
            }
        }
        System.out.println(ans);
    }

    static class FastScanner {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer("");

        String next() {
            while (!st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}
